// Sources to check. Reddit search RSS is a real public feed.
// Trustpilot / Google Reviews / X need the user's own access — see SETUP.md.
// NEVER invent a mention: a source that fails simply yields no mentions.
const keywords = 'YOUR_KEYWORDS'; // e.g. 'Sivasai Boggu' or a brand name, comma-separated
const sources = [
  { source: 'Reddit', type: 'rss',
    url: 'https://old.reddit.com/search.rss?q=' + encodeURIComponent(keywords) + '&sort=new' },
  { source: 'Trustpilot', type: 'http', url: 'YOUR_TRUSTPILOT_COMPANY_URL' },
  { source: 'Google Reviews', type: 'http', url: 'YOUR_GOOGLE_REVIEWS_URL' },
  { source: 'X', type: 'http', url: 'YOUR_X_SEARCH_API_URL' }
];
return sources.map(s => ({ json: { ...s, keywords } }));

// Normalise each source's response into mentions {source, title, text, url, date}.
// RSS items carry title/link; HTML pages fall back to link scraping.
// If a source returns nothing usable, it contributes zero mentions.
const out = [];
for (const item of $input.all()) {
  const src = item.json.source || 'unknown';
  const raw = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json.data || item.json);
  let found = [];
  try {
    const parsed = JSON.parse(raw);
    const arr = Array.isArray(parsed) ? parsed : (parsed.items || parsed.results || parsed.data || []);
    found = arr.map(r => ({ title: r.title || '', text: r.selftext || r.body || r.text || '', url: r.link || r.url || '', date: r.pubDate || r.created || '' }));
  } catch (e) {
    const links = [...raw.matchAll(/<a[^>]+href=\"([^\"]+)\"[^>]*>([^<]{5,160})<\/a>/g)];
    found = links.map(m => ({ title: m[2].trim(), text: '', url: m[1], date: '' }));
  }
  for (const f of found) {
    if (!f.title && !f.text) continue;
    out.push({ json: { source: src, title: f.title, text: f.text || f.title,
      url: f.url || '', date: f.date || new Date().toISOString(), foundAt: new Date().toISOString() } });
  }
}
return out;

