// Parse the sentiment JSON; on failure mark sentiment 'unknown' so the
// mention is logged but never treated as negative.
const raw = $input.first().json.output || $input.first().json.text || '';
const prev = $('Split In Batches').first().json;
let p = {};
try { p = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { p = m ? JSON.parse(m[0]) : {}; } catch (e2) { p = {}; }
}
return [{ json: { ...prev, sentiment: ['positive', 'neutral', 'negative'].includes(p.sentiment) ? p.sentiment : 'unknown',
  score: typeof p.score === 'number' ? p.score : 0, topic: p.topic || '',
  summary: p.summary || '', draftReply: p.draftReply || '' } }];

