// Aggregate the last 7 days of logged mentions into a trend summary.
// Counts only what the Mentions sheet actually contains.
const now = Date.now();
const WEEK = 7 * 24 * 60 * 60 * 1000;
const rows = $input.all().map(i => i.json);
const week = rows.filter(r => (now - new Date(r['Found At'] || r.foundAt || 0).getTime()) <= WEEK);
const count = s => week.filter(r => (r.Sentiment || r.sentiment) === s).length;
const bySource = {};
for (const r of week) { const s = r.Source || r.source || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
const byDay = {};
for (const r of week) { const d = (r['Found At'] || r.foundAt || '').slice(0, 10); byDay[d] = (byDay[d] || 0) + 1; }
const report = [
  'Reputation Radar — weekly trend (' + new Date(now - WEEK).toISOString().slice(0, 10) + ' to ' + new Date(now).toISOString().slice(0, 10) + ')',
  'Total mentions: ' + week.length,
  'Positive: ' + count('positive') + ' | Neutral: ' + count('neutral') + ' | Negative: ' + count('negative') + ' | Unknown: ' + count('unknown'),
  'By source: ' + JSON.stringify(bySource),
  'By day: ' + JSON.stringify(byDay)
].join('\n');
return [{ json: { weekStart: new Date(now - WEEK).toISOString().slice(0, 10),
  weekEnd: new Date(now).toISOString().slice(0, 10), total: week.length,
  positive: count('positive'), neutral: count('neutral'), negative: count('negative'),
  unknown: count('unknown'), bySource, byDay, report } }];

